#!/usr/bin/env bash
set -euo pipefail

SKILL_NAME="revdoku"
# BEGIN GENERATED INSTALLER MANIFEST
# Generated by scripts/generate-installer-manifest.rb; do not edit by hand.
INSTALL_BASE=https://raw.githubusercontent.com/revdoku/revdoku/main
CLIENT_VERSION=1.0.490
expected_sha256() {
  case "$1" in
    skills/revdoku/SKILL.md) printf '%s\n' '72ea04bb402d4738c78c24c9b03194a3cf1bed35a9c05d214a2a19dcde64038b' ;;
    skills/revdoku/scripts/revdoku.sh) printf '%s\n' '6da11462d9e988978e4214fee90cb8875748bab801143e43b48f7419e1ee6e52' ;;
    skills/revdoku/bin/revdoku) printf '%s\n' '61db96238f2cbfa8ed6dfd4e1c872bd929c7564ff0b3ac0ab0a45292b7b5e3a2' ;;
    *) die "unknown installer payload: $1" ;;
  esac
}
# END GENERATED INSTALLER MANIFEST
AGENT="${REVDOKU_AGENT:-auto}"
USER_BIN_DIR="${REVDOKU_BIN_DIR:-${HOME}/.revdoku/bin}"
JQ_VERSION="1.8.1"
JQ_BASE_URL="https://github.com/jqlang/jq/releases/download/jq-${JQ_VERSION}"
STAGING_DIR=""
INSTALL_TEMP=""

cleanup() {
  [[ -z "$INSTALL_TEMP" ]] || rm -f "$INSTALL_TEMP"
  [[ -z "$STAGING_DIR" ]] || rm -rf "$STAGING_DIR"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
trap 'exit 129' HUP

SCRIPT_PATH="${BASH_SOURCE[0]:-}"
SCRIPT_DIR=""
if [[ -n "$SCRIPT_PATH" && -f "$SCRIPT_PATH" ]]; then
  SCRIPT_DIR="$(cd "$(dirname "$SCRIPT_PATH")" && pwd)"
fi

die() {
  echo "error: $1" >&2
  exit 1
}

need_cmd() {
  command -v "$1" >/dev/null 2>&1 || die "requires $1"
}

sha256_file() {
  local path="$1"
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$path" | awk '{print $1}'
    return
  fi
  if command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$path" | awk '{print $1}'
    return
  fi
  if command -v openssl >/dev/null 2>&1; then
    openssl dgst -sha256 "$path" | awk '{print $2}'
    return
  fi
  die "requires sha256sum, shasum, or openssl"
}

detect_jq_asset() {
  local os arch
  os="$(uname -s | tr '[:upper:]' '[:lower:]')"
  arch="$(uname -m)"

  case "$os/$arch" in
    darwin/arm64)
      echo "jq-macos-arm64|a9fe3ea2f86dfc72f6728417521ec9067b343277152b114f4e98d8cb0e263603"
      ;;
    darwin/x86_64)
      echo "jq-macos-amd64|e80dbe0d2a2597e3c11c404f03337b981d74b4a8504b70586c354b7697a7c27f"
      ;;
    linux/x86_64)
      echo "jq-linux-amd64|020468de7539ce70ef1bceaf7cde2e8c4f2ca6c3afb84642aabc5c97d9fc2a0d"
      ;;
    linux/aarch64|linux/arm64)
      echo "jq-linux-arm64|6bc62f25981328edd3cfcfe6fe51b073f2d7e7710d7ef7fcdac28d4e384fc3d4"
      ;;
    *)
      die "unsupported platform for bundled jq: ${os}/${arch}"
      ;;
  esac
}

local_asset_candidates() {
  local repo_path="$1"
  [[ -n "$SCRIPT_DIR" ]] || return

  case "$repo_path" in
    "skills/${SKILL_NAME}/SKILL.md")
      printf '%s\n' \
        "${SCRIPT_DIR}/skills/${SKILL_NAME}/SKILL.md" \
        "${SCRIPT_DIR}/skill/SKILL.md"
      ;;
    "skills/${SKILL_NAME}/scripts/revdoku.sh")
      printf '%s\n' \
        "${SCRIPT_DIR}/skills/${SKILL_NAME}/scripts/revdoku.sh" \
        "${SCRIPT_DIR}/skill/scripts/revdoku.sh"
      ;;
    "skills/${SKILL_NAME}/bin/revdoku")
      printf '%s\n' \
        "${SCRIPT_DIR}/skills/${SKILL_NAME}/bin/revdoku" \
        "${SCRIPT_DIR}/bin/revdoku"
      ;;
  esac
}

copy_local_asset_if_available() {
  local repo_path="$1"
  local target="$2"
  local candidate

  while IFS= read -r candidate; do
    [[ -n "$candidate" && -f "$candidate" ]] || continue
    cp "$candidate" "$target"
    return 0
  done < <(local_asset_candidates "$repo_path")

  return 1
}

download_file() {
  local repo_path="$1"
  local target="$2"
  local expected actual
  expected="$(expected_sha256 "$repo_path")"

  if ! copy_local_asset_if_available "$repo_path" "$target"; then
    need_cmd curl
    curl --proto '=https' --proto-redir '=https' -fsSL "${INSTALL_BASE}/${repo_path}" -o "$target"
  fi
  actual="$(sha256_file "$target")"
  if [[ "$actual" != "$expected" ]]; then
    die "checksum mismatch for ${repo_path}; fetch the current Revdoku installer and retry"
  fi
}

prepare_payload() {
  STAGING_DIR="$(mktemp -d)"
  download_file "skills/${SKILL_NAME}/SKILL.md" "$STAGING_DIR/SKILL.md"
  download_file "skills/${SKILL_NAME}/scripts/revdoku.sh" "$STAGING_DIR/revdoku.sh"
  download_file "skills/${SKILL_NAME}/bin/revdoku" "$STAGING_DIR/revdoku"

  command -v jq >/dev/null 2>&1 && return

  local asset expected candidate root
  IFS="|" read -r asset expected < <(detect_jq_asset)
  for root in "${skill_roots[@]}"; do
    candidate="$root/skills/$SKILL_NAME/bin/jq"
    if [[ -x "$candidate" ]] && [[ "$(sha256_file "$candidate")" == "$expected" ]]; then
      cp "$candidate" "$STAGING_DIR/jq"
      break
    fi
  done
  if [[ ! -f "$STAGING_DIR/jq" && -x "$USER_BIN_DIR/jq" ]] && [[ "$(sha256_file "$USER_BIN_DIR/jq")" == "$expected" ]]; then
    cp "$USER_BIN_DIR/jq" "$STAGING_DIR/jq"
  fi
  if [[ ! -f "$STAGING_DIR/jq" ]]; then
    need_cmd curl
    curl --proto '=https' --proto-redir '=https' -fsSL "${JQ_BASE_URL}/${asset}" -o "$STAGING_DIR/jq"
  fi
  [[ "$(sha256_file "$STAGING_DIR/jq")" == "$expected" ]] || die "downloaded jq checksum mismatch"
}

atomic_install() {
  local source="$1" target="$2" mode="$3"
  INSTALL_TEMP="$(mktemp "${target}.tmp.XXXXXX")"
  cp "$source" "$INSTALL_TEMP"
  chmod "$mode" "$INSTALL_TEMP"
  mv -f "$INSTALL_TEMP" "$target"
  INSTALL_TEMP=""
}

install_skill_to() {
  local root="$1"
  local skill_dir="${root}/skills/${SKILL_NAME}"
  local scripts_dir="${skill_dir}/scripts"
  local bin_dir="${skill_dir}/bin"

  mkdir -p "$scripts_dir" "$bin_dir"
  atomic_install "$STAGING_DIR/SKILL.md" "${skill_dir}/SKILL.md" 0644
  atomic_install "$STAGING_DIR/revdoku.sh" "${scripts_dir}/revdoku.sh" 0755
  atomic_install "$STAGING_DIR/revdoku" "${bin_dir}/revdoku" 0755
  if [[ -f "$STAGING_DIR/jq" ]]; then
    atomic_install "$STAGING_DIR/jq" "${bin_dir}/jq" 0755
  fi

  echo "Installed ${SKILL_NAME} to ${skill_dir}"
}

install_user_command() {
  mkdir -p "$USER_BIN_DIR"
  atomic_install "$STAGING_DIR/revdoku" "${USER_BIN_DIR}/revdoku" 0755
  if [[ -f "$STAGING_DIR/jq" ]]; then
    atomic_install "$STAGING_DIR/jq" "${USER_BIN_DIR}/jq" 0755
  fi
  echo "Installed command to ${USER_BIN_DIR}/revdoku"
}

# Version belongs to the verified payload, not to an environment override.
write_client_version() {
  local config_dir="${REVDOKU_CONFIG_DIR:-$(dirname "$USER_BIN_DIR")}"
  mkdir -p "$config_dir"
  printf '%s\n' "$CLIENT_VERSION" > "$STAGING_DIR/client_version"
  atomic_install "$STAGING_DIR/client_version" "${config_dir}/client_version" 0644
}

main() {
  [[ -z "${REVDOKU_INSTALL_BASE+x}" ]] || die "REVDOKU_INSTALL_BASE is no longer supported; use the official installer or run install.sh from a complete local checkout"
  local codex_root="${CODEX_HOME:-${HOME}/.codex}"
  local claude_root="${CLAUDE_HOME:-${HOME}/.claude}"
  local cursor_root="${CURSOR_HOME:-${HOME}/.cursor}"
  local antigravity_root="${ANTIGRAVITY_HOME:-${HOME}/.gemini/antigravity-cli}"
  local opencode_root="${OPENCODE_HOME:-${XDG_CONFIG_HOME:-${HOME}/.config}/opencode}"
  local grok_root="${GROK_HOME:-${HOME}/.grok}"
  local hermes_root="${HERMES_HOME:-${HOME}/.hermes}"
  local openclaw_root="${OPENCLAW_HOME:-${HOME}/.openclaw}"
  local skill_roots=() root

  case "$AGENT" in
    auto)
      skill_roots+=("$codex_root")
      if [[ -d "$claude_root" ]] || command -v claude >/dev/null 2>&1; then
        skill_roots+=("$claude_root")
      fi
      if [[ -d "$cursor_root" ]] || command -v cursor-agent >/dev/null 2>&1; then
        skill_roots+=("$cursor_root")
      fi
      if [[ -d "$antigravity_root" ]] || command -v antigravity >/dev/null 2>&1; then
        skill_roots+=("$antigravity_root")
      fi
      if [[ -d "$opencode_root" ]] || command -v opencode >/dev/null 2>&1; then
        skill_roots+=("$opencode_root")
      fi
      if [[ -d "$grok_root" ]] || command -v grok >/dev/null 2>&1; then
        skill_roots+=("$grok_root")
      fi
      if [[ -d "$hermes_root" ]] || command -v hermes >/dev/null 2>&1; then
        skill_roots+=("$hermes_root")
      fi
      if [[ -d "$openclaw_root" ]] || command -v openclaw >/dev/null 2>&1; then
        skill_roots+=("$openclaw_root")
      fi
      ;;
    codex)
      skill_roots+=("$codex_root")
      ;;
    claude|claude-code)
      skill_roots+=("$claude_root")
      ;;
    cursor)
      skill_roots+=("$cursor_root")
      ;;
    antigravity)
      skill_roots+=("$antigravity_root")
      ;;
    opencode)
      skill_roots+=("$opencode_root")
      ;;
    grok|grok-build)
      skill_roots+=("$grok_root")
      ;;
    hermes)
      skill_roots+=("$hermes_root")
      ;;
    openclaw)
      skill_roots+=("$openclaw_root")
      ;;
    both)
      skill_roots+=("$codex_root")
      skill_roots+=("$claude_root")
      ;;
    all)
      skill_roots+=("$codex_root")
      skill_roots+=("$claude_root")
      skill_roots+=("$cursor_root")
      skill_roots+=("$antigravity_root")
      skill_roots+=("$opencode_root")
      skill_roots+=("$grok_root")
      skill_roots+=("$hermes_root")
      skill_roots+=("$openclaw_root")
      ;;
    *)
      die "invalid REVDOKU_AGENT=${AGENT}; use auto, codex, claude-code, cursor, antigravity, opencode, grok-build, hermes, openclaw, both, or all"
      ;;
  esac

  prepare_payload
  for root in "${skill_roots[@]}"; do
    install_skill_to "$root"
  done
  install_user_command
  write_client_version
  echo ""
  echo "Revdoku is ready. Ask your agent what to publish, or run:"
  echo "  ${USER_BIN_DIR}/revdoku p <folder>"
  echo "Browser sign-in opens automatically when needed."
}

main "$@"
